<?php
class RolModel {private $db;public function __construct(PDO $db){$this->db=$db;}
public function datos():array{return ['roles'=>$this->db->query("SELECT r.*,COUNT(DISTINCT ur.id_usuario) usuarios,COUNT(DISTINCT rp.id_permiso) permisos,GROUP_CONCAT(DISTINCT rp.id_permiso) ids_permisos FROM roles r LEFT JOIN usuario_rol ur ON ur.id_rol=r.id_rol LEFT JOIN rol_permiso rp ON rp.id_rol=r.id_rol GROUP BY r.id_rol ORDER BY r.nombre")->fetchAll(),'permisos'=>$this->db->query("SELECT * FROM permisos ORDER BY clave")->fetchAll()];}
public function guardar(array $d):void{$id=(int)($d['id_rol']??0);$this->db->beginTransaction();try{if($id){$this->db->prepare('UPDATE roles SET nombre=?,estado=? WHERE id_rol=?')->execute([trim($d['nombre']),$d['estado'],$id]);}else{$this->db->prepare("INSERT INTO roles(nombre,estado) VALUES(?,'ACTIVO')")->execute([trim($d['nombre'])]);$id=(int)$this->db->lastInsertId();}$this->db->prepare('DELETE FROM rol_permiso WHERE id_rol=?')->execute([$id]);$s=$this->db->prepare('INSERT INTO rol_permiso(id_rol,id_permiso) VALUES(?,?)');foreach($d['permisos']??[] as $p)$s->execute([$id,(int)$p]);$this->db->commit();}catch(Throwable $e){$this->db->rollBack();throw $e;}}
}
